import { performance } from 'node:perf_hooks';
import { readTerms,classifyInput,classifyPreactiveRoute,constitutionalFingerprint,sha256 } from './contract.mjs';
import { withWriterLock,loadState,readLedger,appendEvent,newEpoch } from './state.mjs';
import { runProbe } from './probe.mjs';
import { preservePendingIntent,presentTermsState,authorizePreaccept,recordCompletedPreacceptAccess,buildPreacceptRemediationReceipt,applyPreacceptRemediation,canAccept,importPreacceptHandoff } from './admission.mjs';
import { transitionPure,bootstrapDecisionPure,nodeDispatchReceiptPure } from './runtime-core.mjs';
import { processActiveTurn } from './runtime-turn.mjs';
import { runtimeRootDescriptor } from './runtime-root-verified.mjs';
import { CHAT_BOOTSTRAP_DEADLINE_MS,CHAT_BOOTSTRAP_EVIDENCE_V2,CANONICAL_COMPOSITION_AUTHORITY,readLocalMaterializationReceipt,totalDeadlineOk,validateChatBootstrapEvidence,validateTransferRemoteHistory,validateActivationContinuationReceipt,validateCanonicalCompositionHandoff } from './bootstrap-semantic.mjs';
import { DEADLINE_RESULT,canResumeActivation } from './deadline-integrity.mjs';
import {buildSessionShell,validateSessionShell,renderSessionShell} from './session-shell.mjs';
function bootstrapReceipt(state,termsDigest,fingerprint,probe,hostEngine,hostSurface,terminal,mode,evidence=null){const material={schema:'ikant-le-bootstrap-receipt/v2',epoch:state.epoch,activation_modality:state.bootstrap?.activation_modality||'SESSION_CHAT_LOCAL',terms_digest:termsDigest,constitutional_fingerprint:fingerprint,source_head:state.bootstrap?.source_head||evidence?.source_head||state.admission?.source_head||null,runtime_root_sha256:state.bootstrap?.runtime_root_sha256||evidence?.runtime_root_sha256||null,transfer_receipt_sha256:state.bootstrap?.transfer_receipt_sha256||evidence?.transfer_receipt_sha256||null,materialization_receipt_sha256:state.bootstrap?.materialization_receipt_sha256||evidence?.materialization_receipt_sha256||null,bootstrap_evidence_receipt_sha256:state.bootstrap?.bootstrap_evidence_receipt_sha256||evidence?.evidence_receipt_sha256||null,deadline_elapsed_ms:state.bootstrap?.deadline_elapsed_ms??evidence?.elapsed_before_runtime_ms??null,deadline_result:state.bootstrap?.deadline_result||evidence?.deadline_result||null,deadline_origin_receipt_sha256:state.bootstrap?.deadline_origin_receipt_sha256||evidence?.deadline_origin_receipt_sha256||null,acceptance_event_id:state.admission?.acceptance_event_id||null,remote_history_sha256:state.bootstrap?.remote_history_sha256||null,transfer_attempt_receipt_sha256:state.bootstrap?.transfer_attempt_receipt_sha256||null,activation_continuation_receipt_sha256:state.bootstrap?.activation_continuation_receipt_sha256||null,activation_executor_receipt_sha256:state.bootstrap?.activation_executor_receipt_sha256||evidence?.activation_executor_receipt_sha256||null,orientation_object_set_sha256:state.bootstrap?.orientation_object_set_sha256||evidence?.orientation_object_set_sha256||null,activation_slo_elapsed_ms:state.bootstrap?.activation_slo_elapsed_ms??evidence?.activation_slo_elapsed_ms??null,activation_slo_exceeded:state.bootstrap?.activation_slo_exceeded===true||evidence?.activation_slo_exceeded===true,integrity_time_gate_required:state.bootstrap?.integrity_time_gate_required!==false&&evidence?.integrity_time_gate_required!==false,host_profile:{surface:hostSurface,engine:hostEngine},probe:{ok:Boolean(probe?.ok),node:probe?.node||null,fs:probe?.fs||null,crypto:probe?.crypto||null,clock:probe?.clock||null,artifact_sink:Boolean(probe?.artifact_sink),warm:Boolean(probe?.warm),executed_provenance_receipt_sha256:probe?.executed_provenance?.receipt_sha256||null},mode,terminal,composition_authority:state.bootstrap?.composition_authority||'NONE',canonical_composition_receipt_sha256:state.bootstrap?.canonical_composition_receipt_sha256||null,canonical_active_readback:state.bootstrap?.canonical_active_readback===true,host_constraints_precede_local_contract:true};return{...material,receipt_sha256:sha256(Buffer.from(JSON.stringify(material)))};}
function recordNodeDispatch(state,input,hostSurface){const receipt=nodeDispatchReceiptPure(input,state,{hostSurface});const s=structuredClone(state);s.admission.last_node_dispatch_receipt=receipt.receipt_sha256;appendEvent('NODE_DISPATCH',s,'Human input entered the local Node runtime before any iKant response path.',{receipt});return{s,receipt};}
function shellize(base){const shell=buildSessionShell({surfaceText:base.stdout,state:loadState(),events:readLedger(),artifacts:base.artifacts||[],release:base.release||null,environmentTelemetry:base.environment_telemetry||null,code:base.code||0});const v=validateSessionShell(shell);if(!v.ok)throw new Error('FAILURE: session shell invalid ('+v.errors.join(',')+')');return{...base,stdout:renderSessionShell(shell),session_shell:shell};}
function human(text,code=0){return shellize({stdout:text,code,artifacts:[],release:null,environment_telemetry:null});}
const RUNTIME_ROUTE_DECLINED_SCHEMA='ikant-le-runtime-route-declined/v1';
function declineToHost(input,route){const material={schema:RUNTIME_ROUTE_DECLINED_SCHEMA,route:'HOST',reason:'NO_EXPLICIT_IKANT_LIFECYCLE_COMMAND',input_sha256:sha256(Buffer.from(String(input??''))),ikant_output:false,preactive_route:route,authority:0};return{...material,receipt_sha256:sha256(Buffer.from(JSON.stringify(material))),stdout:'',code:0,artifacts:[],release:null,environment_telemetry:null,session_shell:null};}function requirePersistedActive(epoch,{canonicalReceiptSha256=null}={}){const r=loadState();if(r?.status!=='ACTIVE'||r?.epoch!==epoch||r?.bootstrap?.terminal!=='ACTIVE')throw new Error('FAILURE: ACTIVE commit readback mismatch');if(canonicalReceiptSha256!==null&&(r?.bootstrap?.composition_authority!==CANONICAL_COMPOSITION_AUTHORITY||r?.bootstrap?.canonical_composition_receipt_sha256!==canonicalReceiptSha256||r?.bootstrap?.canonical_active_readback!==true))throw new Error('FAILURE: canonical ACTIVE authority readback mismatch');return r;}
function canonicalEvidenceFromHandoff(handoff){const root=runtimeRootDescriptor(),pre=handoff?.direct_handoff?.execution_input?.preaccept_handoff,cv=validateCanonicalCompositionHandoff(handoff,{sourceHead:handoff?.source_head,runtimeRootSha256:root?.runtime_root_sha256,runtimeRootDescriptor:root,orientationObjects:pre?.orientation_objects||[]});if(!cv.ok)throw new Error('canonical composition handoff invalid: '+cv.errors.join(','));const localMaterialization=readLocalMaterializationReceipt();if(localMaterialization?.schema!=='ikant-le-runtime-root-materialization/v2'||localMaterialization?.source_head!==handoff.source_head||localMaterialization?.runtime_root_sha256!==handoff.runtime_root_sha256||localMaterialization?.activation_executor_receipt_sha256!==cv.activation_executor?.receipt_sha256||localMaterialization?.reopen_verified!==true||localMaterialization?.atomic_publish!==true)throw new Error('canonical local materialization unavailable or not bound to handoff');const material={schema:CHAT_BOOTSTRAP_EVIDENCE_V2,source_head:handoff.source_head,runtime_root_sha256:handoff.runtime_root_sha256,activation_executor_receipt_sha256:cv.activation_executor.receipt_sha256,activation_executor:cv.activation_executor,materialization_receipt_sha256:localMaterialization.receipt_sha256,authority:0};return{preacceptHandoff:cv.preaccept_handoff,evidence:{...material,receipt_sha256:sha256(Buffer.from(JSON.stringify(material)))},canonicalReceiptSha256:handoff.receipt_sha256};}
export function canonicalActiveReadback({expectedReceiptSha256=null}={}){const s=loadState(),receipt=s?.bootstrap?.canonical_composition_receipt_sha256||null,ok=s?.status==='ACTIVE'&&s?.bootstrap?.terminal==='ACTIVE'&&s?.bootstrap?.composition_authority===CANONICAL_COMPOSITION_AUTHORITY&&s?.bootstrap?.canonical_active_readback===true&&/^[a-f0-9]{64}$/.test(String(receipt||''))&&(expectedReceiptSha256===null||receipt===expectedReceiptSha256);return{schema:'ikant-le-c59-canonical-active-readback/v1',ok,state:s?.status||null,terminal:s?.bootstrap?.terminal||null,composition_authority:s?.bootstrap?.composition_authority||'NONE',canonical_composition_receipt_sha256:receipt,source_head:s?.bootstrap?.source_head||s?.admission?.source_head||null,runtime_root_sha256:s?.bootstrap?.runtime_root_sha256||null,authority:0};}
export function runCanonicalSessionChat(input,{canonicalCompositionHandoff,...opts}={}){if(String(input)!=='I ACCEPT')throw new Error('canonical SESSION_CHAT_LOCAL activation requires exact I ACCEPT');if(!canonicalCompositionHandoff)throw new Error('canonical composition handoff required');const bound=canonicalEvidenceFromHandoff(canonicalCompositionHandoff);if(opts.preacceptHandoff!==undefined||opts.postAcceptBootstrapEvidence!==undefined)throw new Error('canonical entry forbids caller-supplied parallel bootstrap evidence');return runCommand('I ACCEPT',{...opts,preacceptHandoff:bound.preacceptHandoff,postAcceptBootstrapEvidence:bound.evidence,canonicalCompositionHandoff});}
function bootstrapOnlyPendingIntent(input){const init=new Set(['inizializza','inizializzazione','initialize','initialise','avvia','attiva','bootstrap']),env=new Set(['ambiente','runtime','ikant','ikant_le','sessione','session','locale','local','controllata','controlled']),structural=new Set(['il','lo','la','i','gli','le','un','una','di','del','della','per','e','and','the','a','an','please','pls','repo','repository']);const raw=String(input??'').normalize('NFKC').toLowerCase().replace(/https?:\/\/github\.com\/luke883i\/ikant_le(?:\.git)?/g,' ikant_le ').replace(/[^\p{L}\p{N}_]+/gu,' ').trim(),words=raw.split(/\s+/).filter(Boolean);return words.length>0&&words.some(w=>init.has(w))&&words.filter(w=>!init.has(w)&&!env.has(w)&&!structural.has(w)).length===0;}
function termsMessage(terms){return`${terms.text.trim()}\n\nTerms digest: ${terms.digest}\n\nSe accetti questi termini nella sessione corrente, rispondi esattamente: I ACCEPT`;}
function finishPendingAfterActive(active,{candidate,hostEngine,hostSurface,resourceGrants,hostObservations,actionReceipt,postActionObservations,terms,resumed=false}={}){const pending=active.admission.pending_intent;if(pending){active.admission.pending_intent=null;if(bootstrapOnlyPendingIntent(pending)){appendEvent('PENDING_INTENT_FULFILLED_BY_ACTIVE',active,resumed?'The preserved bootstrap-only intent is satisfied by recovered ACTIVE.':'The preserved request was pure bootstrap control and is satisfied by the ACTIVE transition without creating a synthetic substantive turn.',{pending_intent_sha256:active.admission.pending_intent_sha256,authority:0});return human(resumed?'iKant è attivo. La recovery ha preservato acceptance, epoch e source identity.':'iKant è attivo. L’intento di inizializzazione è stato soddisfatto dalla transizione ACTIVE; non viene creato un turno cognitivo artificiale.');}appendEvent('PENDING_INTENT_RESUME',active,resumed?'The original substantive request is resumed once after recovered ACTIVE.':'The original substantive request is resumed automatically after successful admission.',{pending_intent_sha256:active.admission.pending_intent_sha256});const pd=recordNodeDispatch(active,pending,hostSurface);return processActiveTurn(pd.s,pending,{candidate,hostEngine,resourceGrants,hostObservations,actionReceipt,postActionObservations},terms,pd.receipt,{resumed:true}).out;}return human(resumed?'iKant è attivo. Recovery same-epoch completata senza nuova acceptance.':'iKant è attivo. La shell narrativa è pronta; ogni prossimo input passerà dal runtime Node e il dettaglio tecnico resterà nel backlog DOCX.');}
function activateExecutorV2(acceptedState,{terms,fingerprint,postAcceptBootstrapEvidence,canonicalCompositionHandoff=null,hostEngine,hostSurface,candidate,resourceGrants,hostObservations,actionReceipt,postActionObservations,runtimeEnteredAt,monotonicNow}={}){const next=structuredClone(acceptedState);next.epoch=newEpoch();next.admission.acceptance_event_id=newEpoch();next.bootstrap.integrity_time_gate_required=false;next.bootstrap.composition_authority=canonicalCompositionHandoff?CANONICAL_COMPOSITION_AUTHORITY:'LEGACY_COMPATIBILITY';next.bootstrap.canonical_composition_receipt_sha256=canonicalCompositionHandoff?.receipt_sha256||null;next.bootstrap.canonical_active_readback=false;appendEvent('ACCEPT',next,'Exact current-session Terms acceptance bound; local activation executor authorized.',{bootstrap_mode:'LOCAL_EXECUTOR',preaccept_handoff_sha256:next.admission.preaccept_handoff_sha256||null,source_head:next.admission.source_head||null,acceptance_event_id:next.admission.acceptance_event_id,acceptance_consumed:true,acceptance_clock_required:false});const root=runtimeRootDescriptor(),localMaterialization=readLocalMaterializationReceipt();let evidence=validateChatBootstrapEvidence(postAcceptBootstrapEvidence,{sourceHead:next.admission.source_head,runtimeRootSha256:root?.runtime_root_sha256,loaderBlobSha1:root?.loader?.blob_sha1,localMaterializationReceipt:localMaterialization,runtimeRootDescriptor:root,orientationObjects:next.admission.orientation_objects,termsDigest:terms.digest});let probe=null;if(evidence.ok)probe=runProbe({warm:false,hostSurface});const localElapsed=Math.max(0,Number(monotonicNow())-Number(runtimeEnteredAt));if(evidence.ok){const total=(Number.isFinite(evidence.activation_slo_elapsed_ms)?evidence.activation_slo_elapsed_ms:0)+localElapsed;evidence={...evidence,activation_slo_elapsed_ms:total,activation_slo_exceeded:total>120000,integrity_time_gate_required:false};}const decision=bootstrapDecisionPure(next,terms.digest,fingerprint,probe,{hostSurface,hostEngine,evidenceValidation:evidence});if(decision.terminal!=='ACTIVE'){const receipt=bootstrapReceipt(decision.state,terms.digest,fingerprint,probe,hostEngine,hostSurface,decision.terminal,decision.mode,evidence);decision.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',decision.state,'Local activation executor path did not reach ACTIVE; no false activation permitted.',{receipt,evidence_errors:evidence.errors||[],activation_slo_exceeded:evidence.activation_slo_exceeded===true});return human(decision.state.bootstrap?.availability?.business_summary||'Non posso dichiararmi attivo: il local activation executor non ha chiuso tutte le prove richieste.',1);}let evidenced=structuredClone(next);evidenced.bootstrap={...decision.state.bootstrap,terminal:'EVIDENCE_VERIFIED',probe:null,integrity_time_gate_required:false,deadline_result:null,deadline_terminal:null,deadline_origin_receipt_sha256:null,deadline_elapsed_ms:null};evidenced.status='ACCEPTED';evidenced.probed=false;evidenced.initialized=false;appendEvent('BOOTSTRAP_EVIDENCE',evidenced,'Local activation executor objects, orientation re-verification and atomic materialization were verified before the live runtime probe.',{source_head:evidence.source_head,runtime_root_sha256:evidence.runtime_root_sha256,activation_executor_receipt_sha256:evidence.activation_executor_receipt_sha256,orientation_object_set_sha256:evidence.orientation_object_set_sha256,materialization_receipt_sha256:evidence.materialization_receipt_sha256,evidence_receipt_sha256:evidence.evidence_receipt_sha256,activation_slo_elapsed_ms:evidence.activation_slo_elapsed_ms,activation_slo_exceeded:evidence.activation_slo_exceeded===true,authority:0});let probed=transitionPure(evidenced,'PROBE',terms.digest,true).state;probed.bootstrap={...evidenced.bootstrap,terminal:'PROBED',probe};appendEvent('PROBE',probed,'Automatic local Node probe passed with real readback and executed-code provenance.',{node:probe.node,fs:probe.fs,warm:false,host_surface:hostSurface,executed_provenance_receipt_sha256:probe?.executed_provenance?.receipt_sha256||null});let active=transitionPure(probed,'INITIALIZE',terms.digest).state;active.bootstrap={...probed.bootstrap,terminal:'ACTIVE',integrity_time_gate_required:false,deadline_result:null,deadline_terminal:null,activation_slo_elapsed_ms:evidence.activation_slo_elapsed_ms,activation_slo_exceeded:evidence.activation_slo_exceeded===true,composition_authority:canonicalCompositionHandoff?CANONICAL_COMPOSITION_AUTHORITY:'LEGACY_COMPATIBILITY',canonical_composition_receipt_sha256:canonicalCompositionHandoff?.receipt_sha256||null,canonical_active_readback:Boolean(canonicalCompositionHandoff)};const receipt=bootstrapReceipt(active,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ACTIVE','LOCAL_EXECUTOR',evidence);active.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('INITIALIZE',active,'iKant epoch initialization completed after local executor content verification, materialization/readback and runtime-owned probe.',{receipt});active=requirePersistedActive(active.epoch,{canonicalReceiptSha256:canonicalCompositionHandoff?.receipt_sha256||null});return finishPendingAfterActive(active,{candidate,hostEngine,hostSurface,resourceGrants,hostObservations,actionReceipt,postActionObservations,terms,resumed:false});}
function resumeExecutorActivation({candidate=null,hostEngine='motore host non dichiarato',hostSurface='LOCAL_NODE_CHAT_HOST',resourceGrants=[],hostObservations=[],actionReceipt=null,postActionObservations=[],postAcceptBootstrapEvidence=null,monotonicNow=()=>performance.now()}={}){const runtimeEnteredAt=monotonicNow();return withWriterLock(()=>{const terms=readTerms(),fingerprint=constitutionalFingerprint();let state=loadState();if(!canResumeActivation(state))return human('Recovery same-epoch non disponibile: admission non recuperabile o binding incompleti.',1);if(postAcceptBootstrapEvidence?.schema!=='ikant-le-chat-bootstrap-evidence/v2')return human('Recovery local-executor negata: manca bootstrap evidence v2.',1);const root=runtimeRootDescriptor(),localMaterialization=readLocalMaterializationReceipt();let evidence=validateChatBootstrapEvidence(postAcceptBootstrapEvidence,{sourceHead:state.admission.source_head,runtimeRootSha256:root?.runtime_root_sha256,loaderBlobSha1:root?.loader?.blob_sha1,localMaterializationReceipt:localMaterialization,runtimeRootDescriptor:root,orientationObjects:state.admission.orientation_objects,termsDigest:terms.digest});let probe=null;if(evidence.ok)probe=runProbe({warm:false,hostSurface});const localElapsed=Math.max(0,Number(monotonicNow())-Number(runtimeEnteredAt));if(evidence.ok){const total=(Number.isFinite(evidence.activation_slo_elapsed_ms)?evidence.activation_slo_elapsed_ms:0)+localElapsed;evidence={...evidence,activation_slo_elapsed_ms:total,activation_slo_exceeded:total>120000,integrity_time_gate_required:false};}const decision=bootstrapDecisionPure(state,terms.digest,fingerprint,probe,{hostSurface,hostEngine,evidenceValidation:evidence});if(decision.terminal!=='ACTIVE'){const receipt=bootstrapReceipt(decision.state,terms.digest,fingerprint,probe,hostEngine,hostSurface,decision.terminal,decision.mode,evidence);decision.state.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('BOOTSTRAP_FAILURE',decision.state,'Same-epoch local executor retry did not reach ACTIVE.',{receipt,evidence_errors:evidence.errors||[]});return human(decision.state.bootstrap?.availability?.business_summary||'Recovery local-executor incompleta; iKant resta non-ACTIVE.',1);}let evidenced=structuredClone(state);evidenced.bootstrap={...decision.state.bootstrap,terminal:'EVIDENCE_VERIFIED',probe:null,integrity_time_gate_required:false,deadline_result:null,deadline_terminal:null,deadline_origin_receipt_sha256:null,deadline_elapsed_ms:null};evidenced.status='ACCEPTED';evidenced.probed=false;evidenced.initialized=false;appendEvent('ACTIVATION_RESUME',evidenced,'Same-epoch local executor retry accepted without new human acceptance or source rebase.',{acceptance_event_id:evidenced.admission.acceptance_event_id,activation_executor_receipt_sha256:evidence.activation_executor_receipt_sha256,content_addressed_retry:true,authority:0});let probed=transitionPure(evidenced,'PROBE',terms.digest,true).state;probed.bootstrap={...evidenced.bootstrap,terminal:'PROBED',probe};appendEvent('PROBE',probed,'Same-epoch local executor recovery probe passed with real readback.',{node:probe.node,fs:probe.fs,host_surface:hostSurface});let active=transitionPure(probed,'INITIALIZE',terms.digest).state;active.bootstrap={...probed.bootstrap,terminal:'ACTIVE',integrity_time_gate_required:false,activation_slo_elapsed_ms:evidence.activation_slo_elapsed_ms,activation_slo_exceeded:evidence.activation_slo_exceeded===true};const receipt=bootstrapReceipt(active,terms.digest,fingerprint,probe,hostEngine,hostSurface,'ACTIVE','LOCAL_EXECUTOR',evidence);active.bootstrap.last_receipt_sha256=receipt.receipt_sha256;appendEvent('INITIALIZE',active,'Same-epoch activation recovery completed after idempotent content-addressed local executor retry.',{receipt});active=requirePersistedActive(active.epoch);return finishPendingAfterActive(active,{candidate,hostEngine,hostSurface,resourceGrants,hostObservations,actionReceipt,postActionObservations,terms,resumed:true});});}
export function runCommand(input,{candidate=null,hostEngine='motore host non dichiarato',hostSurface='LOCAL_NODE_CHAT_HOST',resourceGrants=[],hostAcquisition=[],hostObservations=[],actionReceipt=null,postActionObservations=[],preacceptHandoff=null,postAcceptBootstrapEvidence=null,canonicalCompositionHandoff=null,monotonicNow=()=>performance.now()}={}){const runtimeEnteredAt=monotonicNow();return withWriterLock(()=>{const terms=readTerms();const fingerprint=constitutionalFingerprint();let state=loadState();const kind=classifyInput(input),preactiveRoute=state.status==='ACTIVE'?null:classifyPreactiveRoute(input);if(kind==='ACCEPT'&&!canonicalCompositionHandoff&&postAcceptBootstrapEvidence?.compatibility_only!==true)return human('Canonical SESSION_CHAT_LOCAL activation requires the repository-issued C59 composition handoff. Legacy activation requires an explicitly compatibility-only evidence object.',1);if(canonicalCompositionHandoff&&kind!=='ACCEPT')return human('Canonical composition handoff is valid only with exact I ACCEPT.',1);if(canonicalCompositionHandoff){const root=runtimeRootDescriptor(),pre=canonicalCompositionHandoff?.direct_handoff?.execution_input?.preaccept_handoff,cv=validateCanonicalCompositionHandoff(canonicalCompositionHandoff,{sourceHead:canonicalCompositionHandoff?.source_head,runtimeRootSha256:root?.runtime_root_sha256,runtimeRootDescriptor:root,orientationObjects:pre?.orientation_objects||[]});if(!cv.ok)return human('Canonical composition handoff rejected ('+cv.errors.join(',')+').',1);if(preacceptHandoff?.source_head!==cv.preaccept_handoff?.source_head||postAcceptBootstrapEvidence?.schema!==CHAT_BOOTSTRAP_EVIDENCE_V2||postAcceptBootstrapEvidence?.activation_executor_receipt_sha256!==cv.activation_executor?.receipt_sha256)return human('Canonical composition binding mismatch.',1);}if(state.status!=='ACTIVE'&&kind==='TURN'&&preactiveRoute.route==='HOST')return declineToHost(input,preactiveRoute);if(postAcceptBootstrapEvidence&&kind!=='ACCEPT')return human('Il post-accept bootstrap evidence può essere usato solo con lo stesso messaggio umano esatto I ACCEPT.',1);if(preacceptHandoff&&kind!=='ACCEPT')return human('Il pre-accept handoff può essere importato solo insieme allo stesso messaggio umano esatto I ACCEPT.',1);if(kind==='ACCEPT'&&preacceptHandoff){const imported=importPreacceptHandoff(state,preacceptHandoff,terms.digest);if(!imported.ok)return human(`Il pre-accept handoff non è valido (${imported.code}); iKant resta non-ACTIVE.`,1);state=imported.state;appendEvent('PREACCEPT_HANDOFF',state,'Host-observed pre-accept context imported into fresh local state without promoting acceptance, probe or initialization.',{handoff_sha256:imported.digest,source_head:imported.source_head,runtime_observed_terms_presentation:false,host_attested_terms_presentation:true,authority:0});}let dispatched=recordNodeDispatch(state,input,hostSurface);state=dispatched.s;const dispatch=dispatched.receipt;if(!dispatch.node20_plus)return human('L’ambiente corrente non dimostra Node.js 20 o superiore; iKant resta non-ACTIVE.',1);
for(const evt of hostAcquisition){if(state.accepted)break;if(evt.completed){const breach=recordCompletedPreacceptAccess(state,evt.action,{target:evt.target});if(breach.breached){state=breach.state;appendEvent('CAPSULE_BREACH',state,'Completed pre-accept access recorded and classified without retroactive authorization.',{action:evt.action,target:evt.target||null,breach_class:breach.breach_class||null});if(breach.terminal==='REMEDIATION_REQUIRED'){const remediation=buildPreacceptRemediationReceipt(state,terms.digest);state=applyPreacceptRemediation(state,remediation,terms.digest);appendEvent('CAPSULE_REMEDIATION',state,'Read-only pre-accept overread quarantined; bounded orientation must be reacquired before evidentiary use.',{remediation_receipt_sha256:remediation.receipt_sha256,historical_incident_preserved:true,retroactive_authorization:false});return human('iKant · RIPREPARA',1);}return human('iKant · NUOVA CHAT',1);}}else{const d=authorizePreaccept(state,evt.action,{target:evt.target,byteCount:evt.byteCount||0,metadataFields:evt.metadataFields||[]});if(!d.allowed)return human('La richiesta di acquisizione pre-accept è fuori dalla capsula consentita; il bootstrap resta fermo.',1);state=d.state;appendEvent('ORIENTATION',state,'Bounded pre-accept orientation operation allowed by capsule.',{action:evt.action,target:evt.target||null});}}
if(state.admission.breached||state.status==='SESSION_NONCONFORMING')return human('Questa chat è marcata non conforme per una rottura pre-accept della capsula. Per una sessione iKant conforme è necessaria una nuova chat.',1);
